add(slug='meta-business-verification-uae-trade-licence',svc='bm',
 title='Meta Business Verification With a UAE Trade Licence: Why It Gets Rejected (2026)',short='Meta verification, UAE trade licence',
 desc='Verifying a UAE business on Meta with a mainland or free-zone trade licence? The mismatches that cause rejections, what to send, and Business Portfolio help for $1,500 if the portfolio is restricted.',
 h1='Meta business verification with a UAE trade licence.',lede='Most rejections are about matching, not about the licence itself.',
 answer='<strong>Meta checks that the legal name, address and phone or website you enter match the document you upload, so with a UAE trade licence use the exact English trade name as printed, the licensed address, and a licence that is still valid.</strong> Free-zone companies should use the free-zone licence and the name it shows, not a brand or Instagram name. If the licence is renewed, upload the renewed copy. A domain on the business name and a matching business email help. If verification failure has led to a restricted Business Portfolio, Unbanz handles Business Portfolio recovery for $1,500, paid upfront with a 100% refund if it fails.',
 cards=[('Exact trade name','As printed in English.'),('Valid licence','Expired licences are rejected.'),('Free zone','Use the free-zone licence name.')],
 sections=[('mismatch','Common mismatches',table([('Brand name instead of legal trade name','Enter the legal trade name; brands go on Pages.'),('“LLC” or “FZ-LLC” dropped or changed','Copy the suffix exactly.'),('Arabic-only name entered','Use the English name printed on the licence.'),('Old address after moving','Renew or amend the licence first, then verify.'),('Expired licence','Upload the renewed licence.')],('Problem','Fix'))),
  ('send','What to have ready',ul(['Current trade licence (mainland Department of Economy or free-zone authority).','A website or email on a domain that matches the business.','A phone number you can receive a call or SMS on.','The same legal name everywhere you enter it.'])),
  ('links','Official links',linkrows([BV,BSH,BIZ]))],
 faqs=[('Does Meta accept free-zone licences?','Meta asks for official documents that show the legal name and address. A valid free-zone licence is that document for a free-zone company.'),('Can I verify with an Emirates ID?','Personal ID is for confirming a person, not the business. Business verification needs business documents.'),('What does Unbanz charge if the portfolio is restricted?','$1,500, upfront, with a 100% refund if it fails.')],
 related=[('/meta-ad-account-disabled-uae/','Meta ad account disabled in the UAE'),('/meta-business-verification-rejected/','Business verification rejected'),('/meta-appeal-links-uae/','Meta appeal links UAE')])

add(slug='meta-business-verification-saudi-commercial-registration',svc='bm',
 title='Meta Business Verification With a Saudi Commercial Registration (CR) (2026)',short='Meta verification, Saudi CR',
 desc='Verifying a Saudi business on Meta with a Commercial Registration? Arabic and English name mismatches, what to upload, and Business Portfolio recovery for $1,500 if verification left the portfolio restricted.',
 h1='Meta business verification with a Saudi CR.',lede='The usual failure is the name: Arabic on the CR, English in the form.',
 answer='<strong>Upload your Commercial Registration from the Ministry of Commerce and enter the business name exactly as it appears on it; if the CR is in Arabic only, enter the Arabic name or add an official document that shows the English name.</strong> Meta compares what you type with the document, so a transliterated or brand name is the most common reason for rejection. Use the registered address and a phone or domain that belongs to the business. If a failed verification has led to a restricted Business Portfolio, Unbanz handles Business Portfolio recovery for $1,500, paid upfront with a 100% refund if it fails.',
 cards=[('Match the CR','Name exactly as registered.'),('Arabic vs English','Pick the one the document shows.'),('Business contact','Domain, email or phone of the business.')],
 sections=[('mismatch','Common mismatches',table([('English brand name, Arabic-only CR','Enter the Arabic name, or add a document with the English name.'),('Transliteration differs (e.g. Al- vs El-)','Copy the spelling on the document.'),('Branch CR used for main company','Use the CR that matches the legal entity you enter.'),('Personal phone number','Use a number tied to the business where possible.')],('Problem','Fix'))),
  ('send','What to have ready',ul(['Commercial Registration certificate from the Ministry of Commerce.','A second document if needed, such as a utility bill or a VAT certificate in the business name.','A website or business email on a matching domain.'])),
  ('links','Official links',linkrows([BV,BSH,BIZ]))],
 faqs=[('Can I write to Meta in Arabic?','Yes. Meta processes Arabic documents and text.'),('Does a freelance licence work?','It is a government document, but it is issued to a person. If the business has a CR, use the CR.'),('What does Unbanz charge?','$1,500 for a restricted Business Portfolio, upfront, with a 100% refund if it fails.')],
 related=[('/meta-ad-account-disabled-saudi-arabia/','Meta ad account disabled in Saudi Arabia'),('/meta-appeal-links-saudi-arabia/','Meta appeal links Saudi Arabia'),('/ar/','Unbanz بالعربية')])

add(slug='facebook-page-hacked-running-scam-ads',svc='page',
 title='Our Facebook Page Was Hacked and Is Running Scam Ads (2026)',short='Page hacked, scam ads running',
 desc='Hackers took over your business Facebook Page and are running scam ads under your name? Stop the damage, warn customers, use Meta’s official routes, and Page recovery for $600 per Page.',
 h1='Our Facebook Page is running scam ads.',lede='A hijacked Page is valuable to scammers because your followers trust it.',
 answer='<strong>Recover the admin profile at facebook.com/hacked, report the ads as scams from the ads themselves, and check Business Support Home for the Page’s status, because Meta often restricts a Page that runs scam ads even when it was hijacked.</strong> If the hacker ran ads from their own ad account, your card may not be charged; if they used yours, block the card now. Warn customers by email, on your website and on other social accounts. If the Page cannot be recovered through Meta’s routes, Unbanz handles Facebook Page recovery for $600 per Page, paid upfront with a 100% refund if it fails.',
 cards=[('Report each ad','From the ad menu.'),('Warn customers','Email, site, other socials.'),('Block the card','If your ad account was used.')],
 sections=[('who','Whose ad account paid for the ads?',table([('Your ad account','Block the card, dispute charges, secure the ad account.'),('The hacker’s ad account using your Page','Your card is not charged, but your Page carries the policy strikes.'),('Not sure','Check the Ad Library for your Page; it shows active ads by Page.')],('Situation','What to do'))),
  ('steps','Steps',ol(['Recover the admin profile at facebook.com/hacked.','Look up your Page in the Ad Library and report each scam ad.','Ask other Page admins to remove unknown people with access.','Check the Page in Business Support Home and request review of any restriction, explaining the hijack.','Post a short warning to customers outside Facebook.'])),
  ('links','Official links',linkrows([HKF,BSH,('Meta Ad Library','https://www.facebook.com/ads/library/','See every active ad running from your Page.'),PAD]))],
 faqs=[('Will the Page be restricted because of the hacker’s ads?','It can be. Explain the hijack in the review, with dates.'),('Will followers lose trust?','A fast public warning helps a lot.'),('What does Unbanz charge?','$600 per Page, upfront, with a 100% refund if it fails.')],
 related=[('/guides/facebook-page-hacked-admin-removed/','Page hacked, admin removed'),('/facebook-hacked-ads-charged-to-my-card/','Hacked ads charged to my card'),('/hacker-removed-me-as-admin-from-business-portfolio/','Hacker removed you as admin')])

add(slug='what-to-tell-a-client-when-their-meta-account-is-restricted',sv='ad',crumb=('Agencies','/white-label-agency/'),
 title='What to Tell a Client When Their Meta Ad Account or Page Is Restricted: Agency Scripts (2026)',short='Agency scripts for restricted accounts',
 desc='For agencies and freelancers: what to say to a client in the first hour, first day and first week after a Meta ad account, Page or Business Portfolio restriction. Honest scripts, no promises.',
 h1='What to tell a client when their Meta account is restricted.',lede='Clients forgive a restriction. They do not forgive surprises or broken promises.',
 answer='<strong>Tell the client the same day: what is restricted, what you have already done, what happens next, and that Meta makes the final decision with no fixed timeline.</strong> Don’t promise a date or an outcome, and don’t suggest running their ads through another account, which Meta can treat as circumvention. Give a plan B for revenue (email, SMS, other ad platforms) and a date for your next update. If the review fails, you can offer done-for-you recovery at fixed fees: ad account $1,200, Business Portfolio $1,500, Page $600 per Page, white-label if you prefer.',
 cards=[('Same day','Tell them before they notice.'),('No promises','Meta decides; say so.'),('Plan B revenue','Channels you control.')],
 sections=[('hour','First hour: message',f'<blockquote><p>“Meta has restricted [the ad account / the Page / the Business Portfolio] for [policy named in the notice]. Your ads are paused. We have already [checked billing, paused flagged ads, saved screenshots] and we will request a review today. Meta makes the final decision and does not give a timeline. Next update from us: [day].”</p></blockquote>'),
  ('day','First day: what to agree',ul(['Who is admin, and who files the review. Only an admin can.','Which revenue channels to push while ads are down.','That nobody opens a new ad account in the meantime.'])),
  ('week','If the review fails',f'<blockquote><p>“Meta rejected the review. There are still options. We can bring in a specialist who handles these cases for a fixed fee, paid upfront with a full refund if it fails. It usually takes 3–7 days but nothing is guaranteed.”</p></blockquote><p>White-label details: {a("/white-label-recovery-fixed-fees-for-agencies/","fees and terms for agencies")}.</p>'),
  ('links','Official links',linkrows([BSH,RRV,TRB]))],
 faqs=[('Should the client file the review or the agency?','Whoever is an admin of the restricted asset. Agree it on day one.'),('Can we promise the account will come back?','No. Meta decides, and promising an outcome causes most client disputes.'),('Will Unbanz contact my client?','Not in a white-label setup. You stay the contact.')],
 related=[('/client-ad-account-restricted-agency-is-admin/','Client ad account restricted, agency is admin'),('/agency-client-confidentiality-account-recovery/','Client confidentiality'),('/white-label-agency/','White-label for agencies')])
